<?php

declare(strict_types=1);

namespace SendGridSDK\V3\VerifiedSenders;

final class Verify extends \SendGridSDK\TwilioSendGridV3APISDK
{
    /** GET /v3/verified_senders/verify/{token} [operationId: VerifySenderToken] */
    /**
     * Verify Sender Request
     *
     * **This endpoint allows you to verify a sender requests.**
     *
     * The token is generated by SendGrid and included in a verification email delivered to the address that's pending verification.
     */
    public static function getByToken(string $token): void
    {
        self::client()->resource(\SendGridSDK\Resources\V3\VerifiedSenders\Verify::class)->getByToken($token);
    }
}
